import {CARDS,CARD_PRESETS,MAX_CUSTOM_CARDS,cardById} from './cards.js';
import {EVENT_CARDS,eventCardById} from './event-cards.js';
import {eventFace,categoryLabel} from './event-card-ui.js';

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const typeName=type=>type==='negative'?'Négative':'Positive';
function cardItem(card,kind){
 const actions=kind==='custom'?`<div class="card-catalog-actions"><button type="button" data-card-edit="${esc(card.id)}">Modifier</button><button type="button" class="light" data-card-remove="${esc(card.id)}">Supprimer</button></div>`:kind==='active'?`<button type="button" class="light" data-card-copy="${esc(card.id)}">Créer une variante</button>`:'';
 return `<article class="card-catalog-item ${esc(card.type)}"><span class="card-catalog-icon" aria-hidden="true">${esc(card.icon)}</span><div><span class="card-catalog-type">${typeName(card.type)}${kind==='legacy'?' · archive':kind==='custom'?' · personnalisée':''}</span><h3>${esc(card.title)}</h3><p>${esc(card.text)}</p>${actions}</div></article>`;
}
function renderLegacyCardEditor(customCards,draft,message=''){
 const preset=cardById(draft.template)||CARD_PRESETS[0],kind=preset.type,options=CARD_PRESETS.filter(card=>card.type===kind);
 return `<main class="card-editor-page"><div class="card-editor-heading"><div><span class="eyebrow">DEPUIS LE MENU PRINCIPAL</span><h1>Éditeur de cartes</h1><p>Retrouve toutes les cartes du jeu et crée les tiennes à partir d’effets éprouvés.</p></div><button type="button" class="light" data-action="home">← Menu principal</button></div><div class="card-editor-layout"><section class="card-editor-form panel"><h2>${draft.id?'Modifier une carte':'Créer une carte'}</h2><label>Type de carte<select id="card-editor-kind"><option value="positive" ${kind==='positive'?'selected':''}>Positive · pour soi</option><option value="negative" ${kind==='negative'?'selected':''}>Négative · pour un adversaire</option></select></label><label>Effet<select id="card-editor-preset">${options.map(card=>`<option value="${esc(card.id)}" ${card.id===preset.id?'selected':''}>${esc(card.title)} — ${esc(card.text)}</option>`).join('')}</select></label><label>Nom de ta carte<input id="card-editor-title" maxlength="50" value="${esc(draft.title||'')}" placeholder="Ex. Belle échappée"/></label><div class="card-editor-preview ${kind}"><span class="card-catalog-icon" aria-hidden="true">${esc(preset.icon)}</span><span>${typeName(kind)}</span><strong>${esc(draft.title||preset.title)}</strong><p>${esc(preset.text)}</p></div><p class="muted">L’effet reste exactement celui indiqué ici. ${kind==='negative'?'Les négatives ne sont piochées qu’à partir de 2 joueurs.':'Les positives peuvent aussi être piochées en solo.'}</p><div class="card-editor-buttons"><button type="button" data-action="card-editor-save" ${!draft.id&&customCards.length>=MAX_CUSTOM_CARDS?'disabled':''}>${draft.id?'Enregistrer la modification':'Ajouter au paquet'}</button><button type="button" class="light" data-action="card-editor-new">Nouvelle carte</button></div><p class="toast" role="status">${esc(message)}</p></section><section class="card-editor-catalog"><div class="card-catalog-toolbar"><div><h2>Catalogue des cartes</h2><p>${CARD_PRESETS.length} cartes actives · ${customCards.length} personnalisée(s) · ${CARDS.filter(c=>c.legacy).length} archives</p></div><div class="card-editor-buttons"><button type="button" class="light" data-action="card-editor-export" ${customCards.length?'':'disabled'}>⬇️ Exporter mes cartes</button><label class="card-import-label">Importer un fichier .json<input id="import-cards" type="file" accept="application/json,.json"/></label></div></div><h3>Mes cartes · ${customCards.length}/${MAX_CUSTOM_CARDS}</h3><div class="card-catalog-grid">${customCards.map(card=>cardItem(card,'custom')).join('')||'<p>Aucune carte personnalisée pour le moment.</p>'}</div><h3>Cartes officielles dans la pioche · ${CARD_PRESETS.length}</h3><div class="card-catalog-grid">${CARD_PRESETS.map(card=>cardItem(card,'active')).join('')}</div><details class="card-archives"><summary>Anciennes cartes conservées pour les sauvegardes · ${CARDS.filter(c=>c.legacy).length}</summary><div class="card-catalog-grid">${CARDS.filter(card=>card.legacy).map(card=>cardItem(card,'legacy')).join('')}</div></details></section></div><p class="card-editor-footnote">Les cartes enregistrées s’ajoutent aux nouvelles parties sur cet appareil. Une partie déjà commencée conserve son propre paquet. Exporte un fichier pour transférer tes cartes ailleurs.</p></main>`;
}
export function renderCardEditor(customCards,draft,message='',eventEdits=[],eventDraft={slotId:'evt-01',templateId:'evt-01',name:'Vent dans le dos',description:'Une brise favorable te pousse sur la route.'}){
 const slot=EVENT_CARDS.find(c=>c.id===eventDraft.slotId)||EVENT_CARDS[0],effect=EVENT_CARDS.find(c=>c.id===eventDraft.templateId&&c.category===slot.category)||slot;
 const preview={...slot,name:eventDraft.name||slot.name,title:eventDraft.name||slot.name,description:eventDraft.description||slot.description,effectText:effect.effectText,effectType:effect.effectType,effectValue:effect.effectValue,terrainCondition:effect.terrainCondition,playTiming:effect.playTiming,icon:effect.icon};
 const categories=[['positive','Positives'],['negative','Négatives'],['climatic','Climatiques'],['permanent','Bonus permanents']];
 const catalog=categories.map(([category,label])=>`<h3>${label} · 10</h3><div class="event-card-catalog">${EVENT_CARDS.filter(c=>c.category===category).map(base=>{const edited=eventEdits.some(item=>item.slotId===base.id),card=eventCardById(base.id,{eventCardEdits:eventEdits});return `<div class="event-catalog-entry">${edited?'<span class="event-edited-tag">Personnalisée</span>':''}${eventFace(card,`<button type="button" data-event-card-edit="${base.id}">Modifier</button>`,true)}</div>`;}).join('')}</div>`).join('');
 const old=renderLegacyCardEditor(customCards,draft,message),archive=old.slice(old.indexOf('<div class="card-editor-layout">'),old.lastIndexOf('</main>')).replace('Créer une carte</h2>','Créer une ancienne variante</h2>').replace('Ajouter au paquet','Archiver la variante').replace('Catalogue des cartes','Catalogue des cartes historiques').replace('Cartes officielles dans la pioche','Anciennes cartes actives').replace('Les cartes enregistrées s’ajoutent aux nouvelles parties sur cet appareil. Une partie déjà commencée conserve son propre paquet. Exporte un fichier pour transférer tes cartes ailleurs.','Ces anciennes variantes ne sont pas ajoutées à la nouvelle pioche de 40 cartes.');
 return `<main class="card-editor-page"><div class="card-editor-heading"><div><span class="eyebrow">DEPUIS LE MENU PRINCIPAL</span><h1>Éditeur des cartes Événement</h1><p>Personnalise une carte officielle sans modifier le nombre de cartes de la pioche ni les règles des parties en cours.</p></div><button type="button" class="light" data-action="home">← Menu principal</button></div><div class="event-editor-layout"><section class="card-editor-form panel"><h2>Personnaliser une carte</h2><label>Carte à remplacer<select id="event-editor-slot">${EVENT_CARDS.map(c=>`<option value="${c.id}" ${c.id===slot.id?'selected':''}>N° ${c.number} · ${esc(c.name)}</option>`).join('')}</select></label><p class="muted">Catégorie fixe : ${esc(categoryLabel[slot.category])}. La pioche garde exactement 40 cartes.</p><label>Effet prédéfini<select id="event-editor-effect">${EVENT_CARDS.filter(c=>c.category===slot.category).map(c=>`<option value="${c.id}" ${c.id===effect.id?'selected':''}>${esc(c.name)} — ${esc(c.effectText)}</option>`).join('')}</select></label><label>Nom de la carte<input id="event-editor-name" maxlength="50" value="${esc(eventDraft.name||slot.name)}"/></label><label>Texte d’ambiance<textarea id="event-editor-description" maxlength="180" rows="3">${esc(eventDraft.description||slot.description)}</textarea></label><div id="event-editor-preview">${eventFace(preview,'',true)}</div><p class="muted">L’effet et ses valeurs restent ceux du modèle choisi. Les bonus et réactions sont gérés par le moteur de jeu.</p><div class="card-editor-buttons"><button type="button" data-action="event-editor-save">Enregistrer pour les prochaines parties</button><button type="button" class="light" data-action="event-editor-reset" ${eventEdits.some(e=>e.slotId===slot.id)?'':'disabled'}>Rétablir la carte officielle</button></div><p class="toast" role="status">${esc(message)}</p></section><section class="card-editor-catalog"><div class="card-catalog-toolbar"><div><h2>Les 40 cartes Événement</h2><p>${eventEdits.length} personnalisée(s) · 10 cartes par catégorie. Clique sur « Modifier » pour choisir une carte.</p></div><div class="card-editor-buttons"><button type="button" class="light" data-action="event-editor-export" ${eventEdits.length?'':'disabled'}>⬇️ Exporter mes variantes</button><label class="card-import-label">Importer un fichier .json<input id="import-event-cards" type="file" accept="application/json,.json"/></label></div></div>${catalog}</section></div><details class="card-archives event-legacy-archive"><summary>Archives de l’ancien système · ouvrir l’ancien éditeur</summary><p class="muted">Les anciennes cartes et variantes restent accessibles pour les sauvegardes antérieures. Elles ne modifient pas la nouvelle pioche.</p>${archive}</details><p class="card-editor-footnote">Ces modifications sont enregistrées sur cet appareil et appliquées uniquement aux nouvelles parties. Une partie déjà commencée garde sa propre version des cartes.</p></main>`;
}
